files.main.tf:
terraform {
  required_version = ">= 1.6"
  required_providers { aws = { source = "hashicorp/aws", version = "~> 5.31" } }
  backend "s3" { bucket = "gantry-tfstate", key = "prod/terraform.tfstate", dynamodb_table = "gantry-locks" }
}

files.modules/network/main.tf:
resource "aws_subnet" "private" {
  count      = 3
  vpc_id     = aws_vpc.main.id
  cidr_block = cidrsubnet(var.cidr, 4, count.index)
}

mutations.content:
resource "aws_sqs_queue" "jobs" {
  name                       = "gantry-jobs"
  visibility_timeout_seconds = 180
  redrive_policy             = jsonencode({ maxReceiveCount = 5 })
}
